            lm3 = (av3 > lm3) ? av3 : lm3;
            k0 += 4 * inc;
        }
        // Merge partial maxes
        lm0 = (lm1 > lm0) ? lm1 : lm0;
        lm2 = (lm3 > lm2) ? lm3 : lm2;
        local_max = (lm2 > lm0) ? lm2 : lm0;

        // Scalar tail for max
        for (; i < LEN_1D; i++) {
            float abs_val = fabsf(a[k0]);
            local_max = (abs_val > local_max) ? abs_val : local_max;
            k0 += inc;
        }

        // Second loop: find first index where abs value equals local_max
